// Browser e2e for the fighting-style builder — the REAL app via `lein e2e-server`.
//
// What this exists to check (none of it is provable from the JVM suite):
//   1. the route→view binding generated by the page-map MACRO actually renders a page
//   2. the shared :props field fragments render as real inputs
//   3. the `:when` conditional display works — tag dropdowns appear only once a bonus is entered
//   4. an authored style saves and its props survive
//
// Prereqs:  lein fig:build && lein garden once && lein e2e-server   (port 8890)
// Run:      node test/e2e/fighting-style-builder.js
const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const { BASE, SHOTS, findChrome, checker, controlFor, fillEffectBonus } = require('./lib');

const { check, report } = checker();

(async () => {
  fs.mkdirSync(SHOTS, { recursive: true });
  const browser = await chromium.launch({ executablePath: findChrome() });
  const page = await browser.newPage({ viewport: { width: 1400, height: 1100 } });
  // Fonts are self-hosted (docs/kb/fonts.md), so the app fetches NOTHING from a third party and a
  // failed request is a real defect. No filtering — that was only needed while Open Sans came from
  // a CDN the sandbox blocked.
  const errors = [];
  const failedRequests = [];
  page.on('pageerror', e => errors.push(String(e)));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('requestfailed', r => failedRequests.push(`${r.url()} (${r.failure() && r.failure().errorText})`));

  await page.goto(`${BASE}/pages/dnd/5e/fighting-style-builder`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(2500);

  const body = await page.textContent('body');
  check('page renders (macro-generated route→view binding)', /Fighting Style/i.test(body),
        `body starts: ${body.trim().slice(0, 70)}`);
  check('no uncaught JS errors on load', errors.length === 0, errors.slice(0, 2).join(' | '));
  check('no failed requests — nothing is fetched from a third party',
        failedRequests.length === 0, failedRequests.slice(0, 2).join(' | '));
  const fontOk = await page.evaluate(async () => {
    try { await document.fonts.ready; return [...document.fonts].some(f => /Open Sans/.test(f.family)); }
    catch (_) { return false; }
  });
  check('Open Sans loaded from local /fonts', fontOk);

  await page.screenshot({ path: path.join(SHOTS, 'fs-builder-empty.png'), fullPage: true });

  // the base fields the generic builder supplies
  for (const label of ['Name', 'Description']) {
    check(`field present: ${label}`, !!(await controlFor(page, label)));
  }

  // The :rows node. The form no longer shows every field of every effect at once — an author adds
  // the effects the style actually has. So the starting state is that NONE of them are on screen,
  // and each appears when its row is added.
  // A row is present when its titled header (the one carrying the remove control) is on screen.
  const rowAbsent = async (title) => page.evaluate((t) => {
    const vis = e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0; };
    return ![...document.querySelectorAll('span')]
      .some(e => e.textContent.trim() === t && vis(e) && e.parentElement.querySelector('i.fa-times'));
  }, title);

  const addRow = async (title) => page.evaluate((t) => {
    const vis = e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0; };
    const b = [...document.querySelectorAll('button')]
      .filter(e => e.textContent.trim() === `+ ${t}` && vis(e))[0];
    if (!b) return false;
    b.click();
    return true;
  }, title);

  for (const label of ['AC Bonus', 'Attack Bonus', 'Damage Bonus']) {
    check(`${label} row is NOT on screen until it is added`, await rowAbsent(label));
  }
  await page.screenshot({ path: path.join(SHOTS, 'fs-builder-empty.png'), fullPage: true });

  for (const label of ['AC Bonus', 'Attack Bonus', 'Damage Bonus']) {
    check(`added the ${label} row`, await addRow(label));
    await page.waitForTimeout(300);
    check(`${label} row appears once it is added`, !(await rowAbsent(label)));
  }

  // :when still governs within a row — tags hidden until the bonus is entered
  // Inside a row the tag is labelled by its SHORT form — "Armor", not "Armor requirement" — since
  // the group header already says AC BONUS. The long form is what the shared fragment carries and
  // is pinned in builder_fields_test.
  const beforeArmorTag = await controlFor(page, 'Armor');
  check(':when hides the Armor tag before a bonus is entered', beforeArmorTag === null);

  check('typed the AC bonus into its row', await fillEffectBonus(page, 'AC Bonus', 1));
  const afterArmorTag = await controlFor(page, 'Armor');
  check(':when reveals the Armor tag once a bonus is entered', !!afterArmorTag);
  check('typing a number raised no JS error (the seq-on-int regression)',
        !errors.some(e => /ISeqable/.test(e)), errors.filter(e => /ISeqable/.test(e))[0] || '');

  // Removing a row clears its data outright, and the row goes back to the add-bar.
  check('removed the Damage Bonus row', await page.evaluate(() => {
    const vis = e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0; };
    const hdr = [...document.querySelectorAll('span')]
      .filter(e => e.textContent.trim() === 'Damage Bonus' && vis(e))[0];
    if (!hdr) return false;
    const x = hdr.parentElement.querySelector('i.fa-times');
    if (!x) return false;
    x.click();
    return true;
  }));
  await page.waitForTimeout(400);
  check('and its row is gone from the form', await rowAbsent('Damage Bonus'));

  // A three-state value in a two-option <select> would DISPLAY a restriction the item does not
  // have, because a select with no matching value shows its first option.
  if (afterArmorTag) {
    const opts = await afterArmorTag.evaluate(el => [...el.options].map(o => o.textContent.trim()));
    check('Armor tag offers an explicit "Both" first', /^both$/i.test((opts[0] || '').trim()),
          `options: ${JSON.stringify(opts)}`);
    const selected = await afterArmorTag.evaluate(el => el.selectedIndex);
    check('and it is what shows while the tag is unset', selected === 0, `selectedIndex=${selected}`);
  }

  // The :classes divvying rule's authoring half. A style with no classes ticked is open to every
  // fighting-style class (the fallback), so this control exists to author the NARROWER case.
  const classLabels = await page.evaluate(() => {
    const vis = e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0; };
    const hdr = [...document.querySelectorAll('div,span')]
      .find(e => /classes that may take this style/i.test(e.textContent.trim()) && e.children.length <= 1);
    if (!hdr) return null;
    for (let n = hdr.parentElement, i = 0; n && i < 4; n = n.parentElement, i++) {
      const names = [...n.querySelectorAll('span')].map(s => s.textContent.trim())
        .filter(t => /^(fighter|paladin|ranger)$/i.test(t));
      if (names.length) return [...new Set(names)];
    }
    return [];
  });
  check('the :classes control offers exactly the classes that HAVE the feature',
        !!classLabels && classLabels.length === 3, JSON.stringify(classLabels));

  const tickedPaladin = await page.evaluate(() => {
    const vis = e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0; };
    const el = [...document.querySelectorAll('span')]
      .filter(e => e.textContent.trim() === 'Paladin' && vis(e))[0];
    if (!el) return false;
    (el.closest('.pointer') || el.parentElement).click();
    return true;
  });
  check('ticked Paladin', tickedPaladin);
  await page.waitForTimeout(500);

  const nameInput = await controlFor(page, 'Name');
  if (nameInput) { await nameInput.fill('Bulwark'); await nameInput.dispatchEvent('change'); }
  await page.waitForTimeout(400);
  await page.screenshot({ path: path.join(SHOTS, 'fs-builder-filled.png'), fullPage: true });

  // and it has to survive the save as a SET of keywords, not the widget's strings
  const sourceInput = await controlFor(page, 'Option Source Name');
  if (sourceInput) { await sourceInput.fill('Divvy Source'); await sourceInput.dispatchEvent('change'); }
  await page.waitForTimeout(300);
  await page.evaluate(() => {
    const vis = e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0; };
    const el = [...document.querySelectorAll('button,div,span')]
      .filter(e => e.children.length <= 2 && /save to browser storage/i.test(e.textContent.trim()) && vis(e))
      .sort((a, b) => a.textContent.length - b.textContent.length)[0];
    if (el) el.click();
  });
  await page.waitForTimeout(900);
  const saved = await page.evaluate(() => {
    try {
      const v = window.cljs.core.get_in.call(
        null, window.cljs.core.deref.call(null, window.re_frame.db.app_db),
        window.cljs.reader.read_string.call(null, '[:plugins "Divvy Source" :orcpub.dnd.e5/fighting-styles]'));
      return window.cljs.core.pr_str.call(null, v);
    } catch (e) { return 'ERR ' + e.message; }
  });
  check('the authored style saves :classes as a set of keywords',
        /:classes #\{:paladin\}/.test(saved), saved.slice(0, 200));
  // The whole claim of the :rows node is that it is an ARRANGEMENT, not a second storage model.
  // The AC bonus typed into a row has to land exactly where the flat form put it.
  check('and the AC bonus typed in a row lands at the same :props path as before',
        /:props \{:ac-bonus \{:bonus 1/.test(saved), saved.slice(0, 200));

  console.log(`\nscreenshots: ${SHOTS}`);
  await browser.close();
  process.exit(report() ? 1 : 0);
})().catch(e => { console.error(e); process.exit(2); });
